import {
    Mesh,
    PlaneGeometry,
    Object3D,
    Texture,
    LinearFilter,
    SRGBColorSpace,
} from 'three/webgpu';
import {
    MeshBasicNodeMaterial,
    color,
    texture,
    uv,
    mix,
    step,
    min,
    sub,
    vec4,
} from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
    // --- Scene placement ----------------------------------------------------
    const position = config.position ?? [0, 0, 0];
    const rotation = config.rotation ?? [0, 0, 0];
    const scale = config.scale ?? [1, 1, 1];

    const root = new Object3D();
    root.position.set(...position);
    root.rotation.set(...rotation);
    root.scale.set(...scale);

    // --- Geometry -----------------------------------------------------------
    const geometry = new PlaneGeometry(1, 1);
    // (size could be driven by config; using unit plane as placeholder)

    // --- Texture -------------------------------------------------------------
    const tex = ctx.textureLoader.load(
        config.assets?.imageUrl ?? '',
        (t) => {
            t.wrapS = t.wrapT = t.REPEAT;
            t.minFilter = LinearFilter;
            t.magFilter = LinearFilter;
            t.colorSpace = SRGBColorSpace;
        }
    );

    // --- Material (accent edge) ---------------------------------------------
    const texNode = texture(tex);
    const uvNode = uv();

    const edgeThickness = 0.04; // relative UV units
    const edgeMask = step(
        edgeThickness,
        min(
            min(uvNode.x, uvNode.y),
            min(sub(1.0, uvNode.x), sub(1.0, uvNode.y))
        )
    );

    const accentCol = color(config.visual?.colors?.accent ?? '#ff2a38');
    const finalColor = mix(texNode, accentCol, edgeMask);

    const material = new MeshBasicNodeMaterial();
    material.colorNode = finalColor;

    // --- Mesh ---------------------------------------------------------------
    const mesh = new Mesh(geometry, material);
    mesh.name = config.id ?? 'badge-collection';
    root.add(mesh);

    // --- Interaction timelines -----------------------------------------------
    const riseTimeline = gsap.timeline({ paused: true });
    riseTimeline.to(root.position, {
        y: `+=${config.behavior?.interactions?.find(i => i.event === 'hover')?.effect?.match(/([0-9.]+)\s*scene\s*units/)?.[1] ?? 0.15}`,
        duration: 0.7,
        ease: 'power3.out',
    });

    // --- Handlers ------------------------------------------------------------
    const handlers = {};

    handlers.hover = () => {
        riseTimeline.timeScale(1).play();
    };
    handlers.unhover = () => {
        riseTimeline.timeScale(1).reverse();
    };
    handlers.click = () => {
        if (typeof ctx.emit === 'function') {
            ctx.emit('hub-collection.select');
        }
    };

    root.userData.handlers = handlers;

    // --- Data binding placeholder --------------------------------------------
    root.userData.dataBinding = {
        source: 'trpc.journal.posts.posts[]',
        target: 'rows[]',
    };

    // --- Cleanup -------------------------------------------------------------
    root.userData.cleanup = () => {
        if (tex instanceof Texture) tex.dispose();
        geometry.dispose();
        material.dispose();
        riseTimeline.kill();
    };

    return root;
}
